const items = $input.all();
// Same kind -> bucket mapping as supabase/functions/twilio-webhook/index.ts
// (kind isn't stored as a bucket name on the row itself).
const groups = {};
for (const item of items) {
  const bucket = item.json.kind === 'photo' ? 'contact-photos' : 'voice-memos';
  if (!groups[bucket]) groups[bucket] = { ids: [], paths: [] };
  groups[bucket].ids.push(item.json.id);
  groups[bucket].paths.push(item.json.storage_path);
}
return Object.keys(groups).map((bucket) => ({ json: { bucket: bucket, ids: groups[bucket].ids, paths: groups[bucket].paths } }));

// Only mark rows purged whose Storage object was actually deleted above --
// mirrors purge-expired-media.mjs's success-only-marks-purged discipline.
// ids are our own server-generated uuids (never user input), but validate
// the shape anyway before splicing into SQL text.
const uuidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const ids = ($input.item.json.ids || []).filter((id) => uuidPattern.test(id));
const quotedIds = ids.map((id) => "'" + id + "'");
const arrayLiteral = quotedIds.length > 0 ? quotedIds.join(',') : 'null';
return { json: { query: 'select * from mark_media_purged(ARRAY[' + arrayLiteral + "]::uuid[]);" } };
